function ContactForm() {
  // Track whether each field has been interacted with (for deferred validation)
  const touched = { fullName: false, email: false, phone: false };

  const fullNameField = FormField({
    id: "fullName",
    label: "Full Name",
    required: true,
    type: "text",
    placeholder: "Jane Smith",
    inputAttrs: { autocomplete: "name" },
  });

  const emailField = FormField({
    id: "email",
    label: "Email Address",
    required: true,
    type: "email",
    placeholder: "jane@example.com",
    inputAttrs: { autocomplete: "email" },
  });

  const phoneField = FormField({
    id: "phone",
    label: "Phone Number",
    required: false,
    type: "tel",
    placeholder: "+1 (555) 000-0000",
    helperText: "Optional. Use international format: +[country code] [area code] [number] — e.g. +1 555 000 0000.",
    inputAttrs: { autocomplete: "tel" },
  });

  const submitBtn = h(
    "button",
    { className: "contact-form__submit", type: "submit" },
    "Send Message"
  );

