    input.addEventListener("blur", () => {
      touched[input.id] = true;
      markValidity(input);
    });
    input.addEventListener("input", () => {
      if (touched[input.id]) markValidity(input);
    });
  });

  function handleSubmit(e) {
    e.preventDefault();

    // On submit, validate all fields and surface issues
    [fullNameField.input, emailField.input, phoneField.input].forEach((input) => {
      touched[input.id] = true;
      markValidity(input);
    });

    if (!form.checkValidity()) {
      const firstInvalid = form.querySelector("[aria-invalid='true']");
      if (firstInvalid) firstInvalid.focus();
      return;
    }

