    const banner = h(
      "div",
      { className: "success-banner", role: "alert" },
      h("p", { className: "success-banner__title" }, "Message sent!"),
      h("p", null, "Thank you for reaching out. Our support team will get back to you shortly.")
    );

    form.replaceWith(banner);
  }

  return form;
}

// ── Page component ─────────────────────────────────────────────────────────

function SupportPage() {
  const header = h(
    "header",
    { className: "support-page__header" },
    h("h1", { className: "support-page__title" }, "Contact Support"),
    h("p", { className: "support-page__subtitle" }, "Fill out the form below and we'll get back to you as soon as possible.")
  );

  return h("main", { className: "support-page" }, header, ContactForm());
}

// ── Mount ──────────────────────────────────────────────────────────────────

document.getElementById("root").appendChild(SupportPage());
