+/**
+ * ContactForm — React-style component structure compiled to vanilla JS.
+ * Renders a support contact form with full name, email, and phone fields.
+ */
+
+// ── Utility helpers ────────────────────────────────────────────────────────
+
+function h(tag, attrs, ...children) {
+  const el = document.createElement(tag);
+  if (attrs) {
+    for (const [key, value] of Object.entries(attrs)) {
+      if (key === "className") {
+        el.setAttribute("class", value);
+      } else if (key.startsWith("on") && typeof value === "function") {
+        el.addEventListener(key.slice(2).toLowerCase(), value);
+      } else if (value !== null && value !== undefined && value !== false) {
+        el.setAttribute(key, value);
+      }
+    }
+  }
+  for (const child of children.flat()) {
+    if (child == null || child === false) continue;
+    el.appendChild(typeof child === "string" ? document.createTextNode(child) : child);
+  }
+  return el;
+}
+
+// ── Sub-components ─────────────────────────────────────────────────────────
+
+function FormField({ id, label, required, type = "text", placeholder, helperText, inputAttrs = {} }) {
+  const labelEl = h(
+    "label",
+    { className: "form-field__label", for: id },
+    label,
+    required ? h("span", { className: "form-field__required", "aria-hidden": "true" }, " *") : null
+  );
+
+  const input = h("input", {
+    className: "form-field__input",
+    id,
+    name: id,
+    type,
+    placeholder: placeholder || "",
+    required: required || null,
+    autocomplete: inputAttrs.autocomplete || null,
+    ...inputAttrs,
+  });
+
+  const children = [labelEl, input];
+
+  if (helperText) {
+    const helperId = `${id}-helper`;
+    input.setAttribute("aria-describedby", helperId);
+    children.push(h("p", { className: "form-field__helper", id: helperId }, helperText));
+  }
+
+  return { el: h("div", { className: "form-field" }, ...children), input };
+}
+
+// ── ContactForm component ──────────────────────────────────────────────────
+
+function ContactForm() {
+  // Track whether each field has been interacted with (for deferred validation)
+  const touched = { fullName: false, email: false, phone: false };
+
+  const fullNameField = FormField({
+    id: "fullName",
+    label: "Full Name",
+    required: true,
+    type: "text",
+    placeholder: "Jane Smith",
+    inputAttrs: { autocomplete: "name" },
+  });
+
+  const emailField = FormField({
+    id: "email",
+    label: "Email Address",
+    required: true,
+    type: "email",
+    placeholder: "jane@example.com",
+    inputAttrs: { autocomplete: "email" },
+  });
+
+  const phoneField = FormField({
+    id: "phone",
+    label: "Phone Number",
+    required: false,
+    type: "tel",
+    placeholder: "+1 (555) 000-0000",
+    helperText: "Optional. Use international format: +[country code] [area code] [number] — e.g. +1 555 000 0000.",
+    inputAttrs: { autocomplete: "tel" },
+  });
+
+  const submitBtn = h(
+    "button",
+    { className: "contact-form__submit", type: "submit" },
+    "Send Message"
+  );
+
+  const form = h(
+    "form",
+    {
+      className: "contact-form",
+      novalidate: "",
+      onSubmit: handleSubmit,
+    },
+    fullNameField.el,
+    emailField.el,
+    phoneField.el,
+    submitBtn
+  );
+
+  // Mark a field invalid visually only after the user has blurred it
